// Sorteia um ângulo do menu A..J excluindo os 3 últimos usados.
// Se o topic já tem ângulo definido, usa ele (prioridade do editor humano).

const todos = ['A','B','C','D','E','F','G','H','I','J'];
const topic = $('Claim next topic').first().json;
const recentes = $input.all().map(i => i.json.a).filter(Boolean);

let escolhido = topic.angulo;
if (!escolhido) {
  const disponiveis = todos.filter(x => !recentes.includes(x));
  escolhido = disponiveis[Math.floor(Math.random() * disponiveis.length)];
}

const descricoes = {
  A: 'Reframe (você pensa X, na verdade é Y) — use pradex-conceito com tituloRiscado',
  B: 'Lista de 3 itens — use pradex-lista no slide central',
  C: 'Viés comportamental nomeado — use pradex-quote + conceito',
  D: 'História/caso anônimo — narrativa em 5-6 slides',
  E: 'Pergunta provocativa ("você sabe quanto...") na capa',
  F: 'Mito vs verdade — 3-4 pares em pradex-conceito com riscado/certo',
  G: 'Comparativo numérico entre 2 cenários ao longo do tempo',
  H: 'Checklist comportamental em 5-7 perguntas',
  I: 'Quote de impacto (Kahneman/Munger/Buffett) — abrir com pradex-quote',
  J: 'Reflexão ensaística — estrutura mais livre'
};

return [{
  json: {
    ...topic,
    angulo: escolhido,
    angulo_descricao: descricoes[escolhido]
  }
}];

