// Parse + valida + persiste carousel + slides no Supabase via REST (do node Supabase no próximo step).
const raw = $input.first().json.message?.content || $input.first().json;
const data = typeof raw === 'string' ? JSON.parse(raw) : raw;
const topic = $('Sortear ângulo').first().json;

if (!Array.isArray(data.slides) || data.slides.length < 6 || data.slides.length > 8) {
  throw new Error('Slides count fora do range 6-8: ' + (data.slides?.length || 0));
}
if (data.slides[0].template !== 'pradex-capa') {
  throw new Error('Slide 1 deve ser pradex-capa');
}

return [{
  json: {
    topic_id: topic.id,
    nicho: topic.nicho,
    angulo: topic.angulo,
    serie: data.serie || topic.serie,
    ordem: data.ordem || topic.ordem_serie,
    titulo: data.titulo_post || topic.tema,
    caption: data.caption,
    hashtags: data.hashtags || [],
    slides: data.slides
  }
}];

// Monta a URL pública e devolve agregado quando termina o lote.
const items = $input.all();
const carouselId = $('Insert carousel').first().json.id;
const urls = items.map(i => {
  const path = `${carouselId}/${i.json.ordem}.png`;
  return `${$env.SUPABASE_URL}/storage/v1/object/public/carousels/${path}`;
});
return [{ json: { carousel_id: carouselId, urls } }];
